package com.example.payment.integrationtest.paymentgateway;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.springframework.test.web.client.match.MockRestRequestMatchers.content;
import static org.springframework.test.web.client.match.MockRestRequestMatchers.header;
import static org.springframework.test.web.client.match.MockRestRequestMatchers.jsonPath;
import static org.springframework.test.web.client.match.MockRestRequestMatchers.method;
import static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;
import static org.springframework.test.web.client.response.MockRestResponseCreators.withStatus;
import static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import java.math.BigDecimal;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.test.web.client.MockRestServiceServer;
import org.springframework.web.client.RestClient;

class HttpPaymentGatewayTest {

    private MockRestServiceServer server;
    private HttpPaymentGateway gateway;

    @BeforeEach
    void setUp() {
        var builder = RestClient.builder().baseUrl("http://provider.test");
        server = MockRestServiceServer.bindTo(builder).build();
        gateway = new HttpPaymentGateway(builder.build());
    }

    private static Money twelveEuros() {
        return new Money(new BigDecimal("12.50"), "eur");
    }

    @Test
    void the_authorization_is_posted_as_json_with_reference_amount_and_currency() {
        server.expect(requestTo("http://provider.test/v1/authorizations"))
                .andExpect(method(HttpMethod.POST))
                .andExpect(header("Content-Type", MediaType.APPLICATION_JSON_VALUE))
                .andExpect(jsonPath("$.reference").value("ORD-7"))
                .andExpect(jsonPath("$.amount").value(12.50))
                .andExpect(jsonPath("$.currency").value("EUR"))
                .andExpect(jsonPath("$.length()").value(3))
                .andRespond(withSuccess("{\"status\":\"approved\"}", MediaType.APPLICATION_JSON));

        gateway.authorize("ORD-7", twelveEuros());

        server.verify();
    }

    @Test
    void an_approved_answer_is_approved() {
        respond("{\"status\":\"approved\"}");

        assertThat(gateway.authorize("ORD-7", twelveEuros())).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_is_declined() {
        respond("{\"status\":\"declined\"}");

        assertThat(gateway.authorize("ORD-7", twelveEuros())).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void unknown_fields_in_the_answer_are_ignored() {
        respond("{\"id\":\"auth_1\",\"status\":\"approved\",\"extra\":{\"a\":1}}");

        assertThat(gateway.authorize("ORD-7", twelveEuros())).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void an_unexpected_status_value_is_never_treated_as_approved() {
        respond("{\"status\":\"pending\"}");

        assertThat(gateway.authorize("ORD-7", twelveEuros())).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_answer_without_a_status_is_never_treated_as_approved() {
        respond("{\"decision\":\"approved\"}");

        assertThat(gateway.authorize("ORD-7", twelveEuros())).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_refusal_is_a_decline_even_when_the_body_says_approved() {
        server.expect(requestTo("http://provider.test/v1/authorizations"))
                .andRespond(withStatus(HttpStatus.PAYMENT_REQUIRED)
                        .contentType(MediaType.APPLICATION_JSON)
                        .body("{\"status\":\"approved\"}"));

        assertThat(gateway.authorize("ORD-7", twelveEuros())).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_refusal_without_a_body_is_a_decline() {
        server.expect(requestTo("http://provider.test/v1/authorizations"))
                .andRespond(withStatus(HttpStatus.PAYMENT_REQUIRED));

        assertThat(gateway.authorize("ORD-7", twelveEuros())).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_rejected_request_is_reported_as_a_failure_not_a_decline() {
        server.expect(requestTo("http://provider.test/v1/authorizations"))
                .andRespond(withStatus(HttpStatus.BAD_REQUEST).contentType(MediaType.APPLICATION_JSON)
                        .body("{\"error\":\"invalid_currency\"}"));

        assertThatThrownBy(() -> gateway.authorize("ORD-7", twelveEuros()))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("400");
    }

    @Test
    void a_provider_outage_is_reported_as_a_failure_not_a_decline() {
        server.expect(requestTo("http://provider.test/v1/authorizations"))
                .andRespond(withStatus(HttpStatus.SERVICE_UNAVAILABLE));

        assertThatThrownBy(() -> gateway.authorize("ORD-7", twelveEuros()))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("503");
    }

    private void respond(String json) {
        server.expect(requestTo("http://provider.test/v1/authorizations"))
                .andRespond(withSuccess(json, MediaType.APPLICATION_JSON));
    }
}
